// не влияет. Кабинету нужен другой счёт — CountSubmissionsForCabinet ниже.
func (q *Queries) CountSubmissions(ctx context.Context, formID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, countSubmissions, formID)
	var count int64
	err := row.Scan(&count)
	return count, err
}

