type VisitUserAgentsRow struct {
	UserAgent string
	Visits    int64
}

// Сырьё списков «устройства / браузеры / ОС»: сгруппированные строки user-agent.
// Разбор — в Go (domain.ParseUserAgent): здесь нет и не должно быть знания о том,
// что Edge представляется Chrome'ом.
func (q *Queries) VisitUserAgents(ctx context.Context, arg VisitUserAgentsParams) ([]VisitUserAgentsRow, error) {
	rows, err := q.db.Query(ctx, visitUserAgents, arg.FormID, arg.FromTs, arg.ToTs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []VisitUserAgentsRow
	for rows.Next() {
		var i VisitUserAgentsRow
		if err := rows.Scan(&i.UserAgent, &i.Visits); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const webhookSubmissionDelivered = `-- name: WebhookSubmissionDelivered :one
SELECT EXISTS (
    SELECT 1 FROM integration_deliveries
    WHERE webhook_id = $1::uuid AND submission_id = $2 AND outcome = 'delivered'
)
`

type WebhookSubmissionDeliveredParams struct {
	WebhookID    uuid.UUID
	SubmissionID pgtype.UUID
}

// Доезжал ли ЭТОТ ответ в эту цель хоть раз. Спрашивается перед повтором — тот
// же вопрос и тот же довод, что у связки Таблиц.
func (q *Queries) WebhookSubmissionDelivered(ctx context.Context, arg WebhookSubmissionDeliveredParams) (bool, error) {
	row := q.db.QueryRow(ctx, webhookSubmissionDelivered, arg.WebhookID, arg.SubmissionID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
